SET SERVEROUTPUT ON
ACCEPT p_nom PROMPT 'Nom du departement : '
DECLARE
  v_nom departement.nom%TYPE := '&p_nom';
BEGIN
  INSERT INTO departement (id_departement, nom)
  VALUES (departement_id_seq.NEXTVAL, v_nom);
  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Departement ' || v_nom || ' insere');
END;
/
- ACCEPT ... PROMPT affiche l'invite ; &p_nom est remplacé par la saisie (entre apostrophes pour du texte).
- departement_id_seq.NEXTVAL fournit l'identifiant.
- Le sujet cite aussi DEPT_ID_SEQ : c'est la même séquence (utiliser le nom de la question 1).

DECLARE
  v_id departement.id_departement%TYPE := &p_id;
  e_inexistant EXCEPTION;
BEGIN
  DELETE FROM departement WHERE id_departement = v_id;
  IF SQL%ROWCOUNT = 0 THEN
    RAISE e_inexistant;
  END IF;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Departement supprime');
EXCEPTION
  WHEN e_inexistant THEN
    DBMS_OUTPUT.PUT_LINE('Erreur : le departement ' || v_id || ' n''existe pas');
  WHEN OTHERS THEN
    ROLLBACK;
    DBMS_OUTPUT.PUT_LINE('Erreur : ' || SQLERRM);   -- par exemple ORA-02292 si des employés dépendent du département
END;
/
- DELETE sans ligne concernée ne lève pas d'exception : on teste SQL%ROWCOUNT.
- Exception utilisateur : déclarer, RAISE, traiter.
- WHEN OTHERS en dernier, avec SQLERRM.

SET SERVEROUTPUT ON
DECLARE
  v_emp   employes.employe_id%TYPE := &p_emp;
  v_total NUMBER;
  v_comm  NUMBER;
BEGIN
  SELECT SUM(montant) INTO v_total
  FROM commandes
  WHERE employe_id = v_emp;                 -- SUM vaut NULL s'il n'y a aucune commande

  IF v_total IS NULL THEN
    v_comm := 0;
  ELSIF v_total < 100000 THEN
    v_comm := 10;
  ELSIF v_total <= 1000000 THEN
    v_comm := 15;
  ELSE
    v_comm := 20;
  END IF;

  UPDATE employes SET commission = v_comm WHERE employe_id = v_emp;
  IF SQL%ROWCOUNT = 0 THEN
    DBMS_OUTPUT.PUT_LINE('Employe inexistant');
  ELSE
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Commission mise a jour : ' || v_comm || ' %');
  END IF;
END;
/
- SUM sans ligne donne NULL : c'est ce qui permet de détecter « aucune commande ».
- Ordre des tests de l'ELSIF : du plus petit seuil au plus grand ; la borne 1 000 000 est incluse dans la tranche à 15 (<=).
- COMMIT après l'UPDATE ; SQL%ROWCOUNT protège contre un employé inexistant.
